#: The venue name. One venue, because one terminal is one account - and
#: `polymarket-runs-two-exchanges` is the warning about assuming otherwise:
#: there, a readable balance proved nothing about whether an order would be
#: accepted, because the account belonged to a different exchange than the
#: signature addressed.
MT5_VENUE = "MT5"

#: Terminals this process started, by container name.
#:
#: Cached for the same reason the IB factory caches its gateways: the data
#: client and the execution client are built separately and both may ask for
#: one, and two containers on one account is two sessions the broker has to
#: choose between. Keyed by name rather than by config so a data and an
#: execution config that differ in an unrelated field still share a terminal.
TERMINALS: dict[str, Any] = {}


def _terminal(config: Any) -> str | None:
    """Start the dockerized terminal this config asks for, and say where it is.

    Returns `None` when the config does not ask for one, which leaves
    `base_url` as given - the lab box, in production. The container is started
    here rather than in the client because a factory's `create` is the last
    synchronous moment before the node runs, and waiting for a terminal to log
    in is a blocking wait that must not happen inside an event loop.
    """
    wanted = getattr(config, "dockerized_terminal", None)
    if wanted is None:
        return None
    from .terminal import DockerizedMT5Terminal

    terminal = DockerizedMT5Terminal(wanted)
    found = TERMINALS.get(terminal.container_name)
    if found is None:
        terminal.safe_start(wait=wanted.timeout)
        TERMINALS[terminal.container_name] = terminal
        found = terminal
    return found.base_url


class MT5LiveDataClientFactory(LiveDataClientFactory):
    """Builds the read side."""

    @staticmethod
    def create(
        loop: asyncio.AbstractEventLoop,
        name: str,
        config: MT5DataClientConfig,
        msgbus: Any,
        cache: Any,
        clock: Any,
    ) -> MT5DataClient:
        venue = Venue(name or MT5_VENUE)
        base_url = _terminal(config)
        if base_url:
            config = config.dict() | {"base_url": base_url}
            config = MT5DataClientConfig(**config)
        bridge = connect(config)
        return MT5DataClient(
            loop=loop,
            client_id=ClientId(name or MT5_VENUE),
            venue=venue,
            msgbus=msgbus,
            cache=cache,
            clock=clock,
            instrument_provider=MT5InstrumentProvider(bridge, venue),
            config=config,
        )


